addOperation.body:
@Operation allTypes[monitor=false,delToClassAllowed=false]():XCore::Element
  let s = Seq{}
  in s := s->including(self.charge);
     s := s->including(self.debit);
     s := s->including(self.revolving);
     s
  end
end

@Operation getAssocName[monitor=false,delToClassAllowed=false](a : Associations::End):XCore::Symbol
  let b = ""
  in if a.name.of() = Symbol
     then b := a.name
     else b := a.name.head().asSymbol()
     end ;
     b
  end
end

@Operation getEndName[monitor=false,delToClassAllowed=false](a : Associations::End):XCore::Symbol
  let b = ""
  in if a.name.of() = Symbol
     then b := a.name
     else b := a.name.head().asSymbol()
     end ;
     b
  end
end

@Operation getLinkName[monitor=false,delToClassAllowed=false](a : Associations::End):XCore::Symbol
  let b = ""
  in if a.name.of() = Symbol
     then b := a.name
     else b := a.name.head().asSymbol()
     end ;
     b
  end
end

@Operation totalValue[monitor=true,delToClassAllowed=false]():Auxiliary::MonetaryValue
  let sum = Auxiliary::MonetaryValue(0.0,Auxiliary::Currency("EUR","EUR",1))
  in self.partsOps()->collect(o |
       sum := sum.add(self.send(o,Seq{}).totalValue()));
     sum
  end
end

@Operation upperHierarchy[monitor=false,delToClassAllowed=false]():XCore::Element
  let s = Set{};
      o = self.of()
  in @While o <> FMMLx::MetaClass do
       s := s->including(o);
       o := o.of()
     end;
     s
  end
end
